      "path": "dsh-plugin/src/index.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport type { SubagentRun } from '@deepseek-ai/dsh-subagent'\nimport type {} from '@deepseek-ai/dsh-subagent'\nimport { spawn } from 'node:child_process'\nimport { randomUUID } from 'node:crypto'\nimport { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises'\nimport { dirname, isAbsolute, relative, resolve } from 'node:path'\nimport { fileURLToPath } from 'node:url'\n\nexport const name = 'forkprobe-dsh'\nexport const inject = ['tools', 'subagents']\n\nconst PACKAGE_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..')\nconst TOOL_NAMES = ['forkprobe_compare', 'forkprobe_resume']\n\nexport interface Config {\n  provider: string\n  pythonExecutable: string\n  maxCandidates: number\n  verdictTimeoutSeconds: number\n  maxDepth: number\n}\n\nexport const Config: z<Config> = z.object({\n  provider: z.string().default('spawn'),\n  pythonExecutable: z.string().default('python3'),\n  maxCandidates: z.natural().min(2).max(8).default(5),\n  verdictTimeoutSeconds: z.natural().min(30).max(7200).default(1800),\n  maxDepth: z.natural().min(1).max(8).default(3),\n})\n\ninterface PreparedSkill {\n  id: string\n  name: string\n  author: string\n  category: string\n  source: string\n  system_prompt: string\n  fingerprint: string\n}\n\ninterface CandidateResult extends PreparedSkill {\n  output: string\n  latency_seconds: number\n  error?: string\n  token_count_method: 'estimated_visible_context'\n  provider_tokens_used: 0\n}\n\ninterface ToolResponse {\n  status: 'selected' | 'ready' | 'awaiting_verdict' | 'no_verdict'\n  reportPath?: string\n  logPath?: string\n  winner?: string\n  winnerName?: string\n  verdictType?: string\n  handoffText?: string\n  selectedOutput?: string\n  judgeWinner?: string\n  message: string\n}\n\nfunction workspacePath(parent: Agent): string {\n  return parent.session.header.cwd || process.cwd()\n}\n\nfunction resolveWorkspaceFile(workspace: string, requested: string | undefined, fallback: string): string {\n  const candidate = resolve(workspace, requested?.trim() || fallback)\n  const rel = relative(workspace, candidate)\n  if (rel.startsWith('..') || isAbsolute(rel)) {\n    throw new Error('ForkProbe output paths must stay inside the active DSH workspace')\n  }\n  return candidate\n}\n\nfunction textFromBlocks(blocks: ContentBlock[]): string {\n  return blocks\n    .filter((block): block is Extract<ContentBlock, { type: 'text' }> => block.type === 'text')\n    .map(block => block.text)\n    .join('')\n}\n\nfunction candidatePrompt(task: string, skill: PreparedSkill): string {\n  return [\n    'You are one isolated ForkProbe candidate inside DeepSeek Harness.',\n    'Complete the original task using only the candidate instructions below.',\n    'Do not compare candidates, call ForkProbe, modify files, or ask follow-up questions.',\n    'Return only the final answer to the original task.',\n    '',\n    `Candidate id: ${skill.id}`,\n    '',\n    '## Candidate instructions',\n    skill.system_prompt,\n    '',\n    '## Original task',\n    task,\n  ].join('\\n')\n}\n\nfunction truncate(value: string, limit: number): string {\n  if (value.length <= limit) return value\n  const half = Math.floor(limit / 2)\n  return `${value.slice(0, half)}\\n\\n[... truncated ${value.length - limit} chars ...]\\n\\n${value.slice(-half)}`\n}\n\nfunction judgePrompt(task: string, results: CandidateResult[], rubric?: string): string {\n  const candidates = results.map(result => [\n    `## Candidate: ${result.id}`,\n    `Name: ${result.name}`,\n    result.error ? `[ERROR] ${result.error}` : truncate(result.output, 5000),\n  ].join('\\n')).join('\\n\\n---\\n\\n')\n  return [\n    'You are ForkProbe\\'s impartial comparison judge.',\n    'Compare candidates for fidelity, correctness, specificity, usefulness, clarity, and natural tone.',\n    'Use a 0-10 score for every candidate. Return JSON only with this exact shape:',\n    '{\"winner_skill_id\":\"candidate id, __tie__, or __none__\",\"verdict_type\":\"pick | tie | none\",\"confidence\":0.0,\"summary\":\"one sentence\",\"reasoning\":\"2-5 sentences\",\"scores\":{\"candidate_id\":{\"score\":0,\"note\":\"short note\"}}}',\n    rubric?.trim() ? `Additional rubric: ${rubric.trim()}` : '',\n    '',\n    '## Original task',\n    truncate(task, 4000),\n    '',\n    '## Candidates',\n    candidates,\n  ].filter(Boolean).join('\\n')\n}\n\nasync function runProcess(\n  command: string,\n  args: string[],\n  cwd: string,\n  signal: AbortSignal,\n): Promise<string> {\n  return new Promise((resolvePromise, reject) => {\n    const child = spawn(command, args, {\n      cwd,\n      env: process.env,\n      shell: false,\n      stdio: ['ignore', 'pipe', 'pipe'],\n    })\n    let stdout = ''\n    let stderr = ''\n    const abort = () => child.kill('SIGTERM')\n    signal.addEventListener('abort', abort, { once: true })\n    child.stdout.setEncoding('utf8')\n    child.stderr.setEncoding('utf8')\n    child.stdout.on('data', chunk => { stdout += String(chunk) })\n    child.stderr.on('data', chunk => { stderr += String(chunk) })\n    child.on('error', reject)\n    child.on('close', code => {\n      signal.removeEventListener('abort', abort)\n      if (signal.aborted) {\n        reject(new Error('ForkProbe operation was cancelled'))\n      } else if (code === 0) {\n        resolvePromise(stdout.trim())\n      } else {\n        reject(new Error(`${command} exited ${String(code)}: ${stderr.trim() || stdout.trim()}`))\n      }\n    })\n  })\n}\n\nasync function startSubagent(\n  ctx: Context,\n  config: Config,\n  parent: Agent,\n  prompt: string,\n  label: string,\n  signal: AbortSignal,\n): Promise<{ output: string; latencySeconds: number; error?: string }> {\n  const provider = ctx.subagents.getProvider(config.provider)\n  if (!provider) throw new Error(`ForkProbe subagent provider \"${config.provider}\" is not available`)\n  if (!provider.capabilities.toolFilter) {\n    throw new Error(`ForkProbe subagent provider \"${config.provider}\" must support tool filtering`)\n  }\n  const startedAt = performance.now()\n  let run: SubagentRun | undefined\n  try {\n    run = await ctx.subagents.start(config.provider, {\n      label,\n      prompt: [{ type: 'text', text: prompt }],\n      parent,\n      signal,\n      toolFilter: { allow: [] },\n      ...(provider.capabilities.depthLimit ? { maxDepth: config.maxDepth } : {}),\n    })\n    const result = await run.result\n    const output = textFromBlocks(result.output)\n    const error = result.stopReason === 'completed'\n      ? undefined\n      : `native DSH subagent ended with ${result.stopReason}`\n    return { output, latencySeconds: (performance.now() - startedAt) / 1000, ...(error ? { error } : {}) }\n  } catch (error: unknown) {\n    return {\n      output: '',\n      latencySeconds: (performance.now() - startedAt) / 1000,\n      error: error instanceof Error ? error.message : String(error),\n    }\n  } finally {\n    if (run) await run.dispose().catch(() => undefined)\n  }\n}\n\nasync function readJson(path: string): Promise<Record<string, unknown>> {\n  return JSON.parse(await readFile(path, 'utf8')) as Record<string, unknown>\n}\n\nasync function findLatestVerdictLog(workspace: string): Promise<string> {\n  const logsDir = resolve(workspace, 'forkprobe-logs')\n  const entries = await readdir(logsDir, { withFileTypes: true })\n  const candidates = entries\n    .filter(entry => entry.isFile() && /^\\d{4}-.*\\.json$/.test(entry.name))\n    .map(entry => resolve(logsDir, entry.name))\n    .sort()\n    .reverse()\n  if (!candidates.length) throw new Error('no ForkProbe logs exist in this workspace')\n\n  const latest = candidates[0]\n  for (const candidate of candidates) {\n    try {\n      const log = await readJson(candidate)\n      if ((log.verdict as Record<string, unknown> | null)?.winner) return candidate\n    } catch {\n      // Ignore an incomplete or unrelated JSON file and keep scanning.\n    }\n  }\n  return latest\n}\n\nasync function waitForVerdict(\n  logPath: string,\n  results: CandidateResult[],\n  timeoutSeconds: number,\n  signal: AbortSignal,\n): Promise<ToolResponse | undefined> {\n  const deadline = Date.now() + timeoutSeconds * 1000\n  while (Date.now() < deadline && !signal.aborted) {\n    try {\n      const log = await readJson(logPath)\n      const verdict = log.verdict as Record<string, unknown> | null\n      if (verdict?.winner) {\n        const winner = String(verdict.winner)\n        const selected = results.find(result => result.id === winner)\n        return {\n          status: 'selected',\n          reportPath: String(log.report_path || ''),\n          logPath,\n          winner,\n          winnerName: String(verdict.winner_name || selected?.name || winner),\n          verdictType: String(verdict.verdict_type || 'pick'),\n          handoffText: String(verdict.handoff_text || ''),\n          ...(selected ? { selectedOutput: selected.output } : {}),\n          message: selected\n            ? `The user selected ${selected.name}. Continue the original task with this selected output and Skill.`\n            : 'The user submitted a tie or none verdict. Follow the verdict instead of the AI judge.',\n        }\n      }\n    } catch {\n      // The log may be between atomic browser updates; retry briefly.\n    }\n    await new Promise(resolvePromise => setTimeout(resolvePromise, 500))\n  }\n  return undefined\n}\n\nfunction responseSchema() {\n  return {\n    type: 'object' as const,\n    additionalProperties: false,\n    properties: {\n      status: { type: 'string' as const, required: true },\n      reportPath: { type: 'string' as const },\n      logPath: { type: 'string' as const },\n      winner: { type: 'string' as const },\n      winnerName: { type: 'string' as const },\n      verdictType: { type: 'string' as const },\n      handoffText: { type: 'string' as const },\n      selectedOutput: { type: 'string' as const },\n      judgeWinner: { type: 'string' as const },\n      message: { type: 'string' as const, required: true },\n    },\n  } as const\n}\n\nfunction renderResponse(_args: unknown, value: ToolResponse): ContentBlock[] {\n  const lines = [value.message]\n  if (value.reportPath) lines.push(`Report: ${value.reportPath}`)\n  if (value.winnerName) lines.push(`User-selected winner: ${value.winnerName}`)\n  if (value.handoffText) lines.push(`Continuation handoff: ${value.handoffText}`)\n  if (value.selectedOutput) lines.push(`Selected output:\\n${value.selectedOutput}`)\n  return [{ type: 'text', text: lines.join('\\n') }]\n}\n\nexport function apply(ctx: Context, config: Config): void {\n  ctx.tools.register(defineTool({\n    name: 'forkprobe_compare',\n    description: 'After the user explicitly confirms a shortlist, run 2-5 text Skill candidates through native DeepSeek Harness subagents in parallel, open a local ForkProbe comparison report, and continue only from the user-selected winner. Never call this before showing the shortlist and receiving confirmation.',\n    parameters: {\n      task: { type: 'string', required: true, description: 'The complete original user task and source text.' },\n      skills: {\n        type: 'array',\n        required: true,\n        items: { type: 'string' },\n        description: 'Confirmed Skill IDs, local paths, or HTTPS GitHub sources. Baseline is added automatically.',\n      },\n      confirmed: { type: 'boolean', required: true, description: 'Must be true only after the user confirmed this shortlist.' },\n      task_type: { type: 'string', description: 'Privacy-safe task category for optional aggregate feedback.' },\n      domain: { type: 'string', description: 'ForkProbe catalog domain; defaults to academic-writing.' },\n      output_path: { type: 'string', description: 'Report path inside the active workspace.' },\n      judge: { type: 'boolean', description: 'Run a native DSH judge after candidate completion; defaults to true.' },\n      judge_rubric: { type: 'string', description: 'Optional extra judge rubric.' },\n      wait_for_verdict: { type: 'boolean', description: 'Wait for the Report Continue button and return the selected output; defaults to true.' },\n    },\n    output: { schema: responseSchema(), render: renderResponse },\n    isConcurrencySafe: () => false,\n    async execute(args, exec): Promise<ToolResponse> {\n      const parent = exec.agent\n      if (!parent) throw new Error('forkprobe_compare requires a calling DSH Agent')\n      if (args.confirmed !== true) {\n        throw new Error('Show the candidate shortlist and obtain explicit user confirmation before calling forkprobe_compare')\n      }\n      if (args.skills.length < 1 || args.skills.length > config.maxCandidates) {\n        throw new Error(`Provide 1-${config.maxCandidates} confirmed Skill references; baseline is added automatically`)\n      }\n\n      const workspace = workspacePath(parent)\n      const runId = randomUUID().slice(0, 8)\n      const workDir = resolve(workspace, '.forkprobe-dsh', runId)\n      await mkdir(workDir, { recursive: true })\n      const skillsPath = resolve(workDir, 'skills.json')\n      const preparedPath = resolve(workDir, 'prepared.json')\n      const manifestPath = resolve(workDir, 'native-results.json')\n      const reportPath = resolveWorkspaceFile(\n        workspace,\n        args.output_path,\n        `forkprobe-dsh-${new Date().toISOString().replace(/[:.]/g, '')}-report.html`,\n      )\n      await writeFile(skillsPath, JSON.stringify(args.skills), 'utf8')\n\n      try {\n        await runProcess(config.pythonExecutable, [\n          resolve(PACKAGE_ROOT, 'scripts/prepare_native_compare.py'),\n          '--skills-json', skillsPath,\n          '--domain', args.domain?.trim() || 'academic-writing',\n          '--output', preparedPath,\n          '--max-candidates', String(config.maxCandidates),\n        ], workspace, exec.signal)\n        const prepared = await readJson(preparedPath)\n        const skills = prepared.skills as PreparedSkill[]\n        if (!Array.isArray(skills) || skills.length < 2) {\n          throw new Error('ForkProbe preparation did not produce at least two distinct candidates')\n        }\n\n        const candidateStart = performance.now()\n        const results = await Promise.all(skills.map(async skill => {\n          const run = await startSubagent(\n            ctx,\n            config,\n            parent,\n            candidatePrompt(args.task, skill),\n            `ForkProbe: ${skill.name}`,\n            exec.signal,\n          )\n          return {\n            ...skill,\n            output: run.output,\n            latency_seconds: run.latencySeconds,\n            ...(run.error ? { error: run.error } : {}),\n            token_count_method: 'estimated_visible_context' as const,\n            provider_tokens_used: 0 as const,\n          }\n        }))\n\n        let judge: Record<string, unknown> = { enabled: false }\n        if (args.judge !== false) {\n          const judgeRun = await startSubagent(\n            ctx,\n            config,\n            parent,\n            judgePrompt(args.task, results, args.judge_rubric),\n            'ForkProbe AI judge',\n            exec.signal,\n          )\n          judge = {\n            enabled: true,\n            output: judgeRun.output,\n            latency_seconds: judgeRun.latencySeconds,\n            ...(judgeRun.error ? { error: judgeRun.error } : {}),\n          }\n        }\n\n        await writeFile(manifestPath, JSON.stringify({\n          schema_version: 1,\n          task_input: args.task,\n          task_type: args.task_type?.trim() || 'text_general',\n          duration_seconds: (performance.now() - candidateStart) / 1000,\n          results: results.map(result => ({\n            skill_id: result.id,\n            skill_name: result.name,\n            skill_author: result.author,\n            skill_category: result.category,\n            system_prompt: result.system_prompt,\n            output: result.output,\n            latency_seconds: result.latency_seconds,\n            token_count_method: result.token_count_method,\n            provider_tokens_used: result.provider_tokens_used,\n            ...(result.error ? { error: result.error } : {}),\n          })),\n          judge,\n        }), 'utf8')\n\n        const finalizedText = await runProcess(config.pythonExecutable, [\n          resolve(PACKAGE_ROOT, 'scripts/finalize_native_compare.py'),\n          '--manifest', manifestPath,\n          '--output', reportPath,\n          '--workspace', workspace,\n          '--verdict-timeout', String(config.verdictTimeoutSeconds),\n        ], workspace, exec.signal)\n        const finalized = JSON.parse(finalizedText) as Record<string, unknown>\n        const ready: ToolResponse = {\n          status: 'ready',\n          reportPath: String(finalized.report_path || reportPath),\n          logPath: String(finalized.log_path || ''),\n          ...(finalized.judge_winner ? { judgeWinner: String(finalized.judge_winner) } : {}),\n          message: finalized.verdict_connected\n            ? 'ForkProbe opened the local report. The AI judge is advisory; wait for the user to click Continue with their chosen winner.'\n            : 'ForkProbe created the report, but the local verdict server was unavailable. Ask the user to review it, then call forkprobe_resume after they select a winner.',\n        }\n\n        if (args.wait_for_verdict === false || !finalized.verdict_connected || !ready.logPath) return ready\n        const selected = await waitForVerdict(ready.logPath, results, config.verdictTimeoutSeconds, exec.signal)\n        return selected || {\n          ...ready,\n          status: 'awaiting_verdict',\n          message: 'The report is ready, but no user verdict arrived before the local wait window ended. Do not use the AI judge as the user choice; call forkprobe_resume after selection.',\n        }\n      } finally {\n        await rm(workDir, { recursive: true, force: true }).catch(() => undefined)\n      }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'forkprobe_resume',\n    description: 'Read the latest submitted ForkProbe Report verdict in this workspace and return the user-selected Skill output so the DSH Agent can continue the original task.',\n    parameters: {\n      log_path: { type: 'string', description: 'Optional ForkProbe log path inside the active workspace.' },\n    },\n    output: { schema: responseSchema(), render: renderResponse },\n    isConcurrencySafe: () => true,\n    async execute(args, exec): Promise<ToolResponse> {\n      const parent = exec.agent\n      if (!parent) throw new Error('forkprobe_resume requires a calling DSH Agent')\n      const workspace = workspacePath(parent)\n      const logPath = args.log_path\n        ? resolveWorkspaceFile(workspace, args.log_path, args.log_path)\n        : await findLatestVerdictLog(workspace)\n      try {\n        const log = await readJson(logPath)\n        const verdict = log.verdict as Record<string, unknown> | null\n        if (!verdict?.winner) {\n          return { status: 'no_verdict', logPath, message: 'No submitted ForkProbe verdict was found yet.' }\n        }\n        const bundlePath = String(log.local_result_bundle_path || '')\n        const bundle = bundlePath ? await readJson(resolveWorkspaceFile(workspace, bundlePath, bundlePath)) : {}\n        const results = Array.isArray(bundle.results) ? bundle.results as Record<string, unknown>[] : []\n        const winner = String(verdict.winner)\n        const selected = results.find(result => String(result.skill_id) === winner)\n        return {\n          status: 'selected',\n          reportPath: String(log.report_path || ''),\n          logPath,\n          winner,\n          winnerName: String(verdict.winner_name || selected?.skill_name || winner),\n          verdictType: String(verdict.verdict_type || 'pick'),\n          handoffText: String(verdict.handoff_text || ''),\n          ...(selected?.output ? { selectedOutput: String(selected.output) } : {}),\n          message: selected\n            ? `Recovered the user-selected winner ${String(selected.skill_name || winner)}. Continue with this output and Skill.`\n            : 'Recovered a tie or none verdict. Follow the user verdict and do not substitute the AI judge recommendation.',\n        }\n      } catch (error: unknown) {\n        return {\n          status: 'no_verdict',\n          logPath,\n          message: `Could not recover a submitted verdict: ${error instanceof Error ? error.message : String(error)}`,\n        }\n      }\n    },\n  }))\n}\n\nexport const __testing = {\n  candidatePrompt,\n  judgePrompt,\n  resolveWorkspaceFile,\n  findLatestVerdictLog,\n  textFromBlocks,\n  toolNames: TOOL_NAMES,\n}\n"
    },
    {
      "path": "scripts/compare.py",
      "content": "\"\"\"\nforkprobe main orchestration: run a task in parallel with and without skill(s).\n\nUsage:\n    python compare.py --input task.txt --skill baseline --skill humanizer --output report.html\n\nv0.10 status: Native DeepSeek Harness plugin support, anonymous Winner feedback, multi-source discovery, artifact comparison, HTML report,\nresearch-report and webpage artifact routing, and local HTML reports\nrendering, local verdict capture, and first artifact comparison flows.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport os\nimport re\nimport sys\nimport time\nimport uuid\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Optional\n\n# Make sibling imports work whether script is run as module or directly\nsys.path.insert(0, str(Path(__file__).parent))\nfrom platform_adapter import detect_platform, spawn_subagent, SubagentResult\nfrom skill_loader import load_skill, LoadedSkill\n\n\n# --- Paths ---\nSCRIPT_DIR = Path(__file__).parent\nPROJECT_DIR = SCRIPT_DIR.parent\nCATALOG_DIR = PROJECT_DIR / \"catalog\"\nLOGS_DIR = Path.cwd() / \"forkprobe-logs\"\nFORKPROBE_VERSION = \"v0.10\"\n\n\n# --- Data structures ---\n\n@dataclass\nclass SkillSpec:\n    \"\"\"One entry in the catalog or a BYO.\"\"\"\n    id: str\n    name: str\n    author: str\n    language: str\n    category: str\n    source: str  # GitHub URL or local path\n    system_prompt: str  # actual prompt to send to subagent\n\n\n@dataclass\nclass RunResult:\n    \"\"\"One row in the final report — output of one subagent.\"\"\"\n    skill_id: str\n    skill_name: str\n    skill_author: str\n    skill_category: str\n    output: str\n    tokens_used: int\n    latency_seconds: float\n    estimated_tokens_used: int = 0\n    provider_tokens_used: int = 0\n    token_count_method: str = \"estimated_visible_context\"\n    qa_warnings: list[str] = field(default_factory=list)\n    error: Optional[str] = None\n\n\n@dataclass\nclass JudgeResult:\n    \"\"\"AI judge recommendation over all candidate outputs.\"\"\"\n    winner_skill_id: Optional[str]\n    verdict_type: str\n    confidence: Optional[float]\n    summary: str\n    reasoning: str\n    scores: dict\n    tokens_used: int\n    latency_seconds: float\n    error: Optional[str] = None\n    raw_output: str = \"\"\n\n\n# --- Catalog loading ---\n\ndef load_catalog(domain: str = \"academic-writing\") -> dict:\n    \"\"\"Load curated skill metadata.\"\"\"\n    catalog_path = CATALOG_DIR / f\"{domain}.json\"\n    if not catalog_path.exists():\n        raise FileNotFoundError(f\"Catalog not found: {catalog_path}\")\n    return json.loads(catalog_path.read_text(encoding=\"utf-8\"))\n\n\ndef split_byo_source(source: str) -> tuple[str, Optional[str]]:\n    \"\"\"\n    Split BYO skill references of the form \"<repo-or-path>#<subdir>\".\n\n    This keeps curated catalog entries simple while allowing recommendations to\n    point at a specific skill inside a multi-skill repo, for example:\n    https://github.com/Yuan1z0825/nature-skills#skills/nature-polishing\n    \"\"\"\n    if \"#\" not in source:\n        return source, None\n    base, _, fragment = source.partition(\"#\")\n    subdir = fragment.strip().strip(\"/\")\n    return base, subdir or None\n\n\ndef resolve_skill(skill_id_or_path: str, catalog: dict) -> SkillSpec:\n    \"\"\"\n    Resolve a skill ID (catalog lookup) or BYO path/URL to a SkillSpec with system prompt.\n\n    - \"baseline\" → bare model with generic helpful-assistant prompt\n    - catalog ID  → look up source + subdir from catalog, clone if needed, parse SKILL.md\n    - URL / path  → BYO: treat as direct source\n    \"\"\"\n    if skill_id_or_path == \"baseline\":\n        return SkillSpec(\n            id=\"baseline\",\n            name=\"Baseline (no skill)\",\n            author=\"—\",\n            language=\"—\",\n            category=\"baseline\",\n            source=\"—\",\n            system_prompt=(\n                \"You are a helpful assistant. Complete the user's task to the best of your ability. \"\n                \"Do not apply any specialized skill or framework — just respond naturally.\"\n            ),\n        )\n\n    # Check catalog\n    for skill_meta in catalog.get(\"skills\", []):\n        if skill_meta[\"id\"] == skill_id_or_path:\n            loaded: LoadedSkill = load_skill(\n                skill_id=skill_meta[\"id\"],\n                source=skill_meta[\"source\"],\n                subdir=skill_meta.get(\"subdir\"),\n            )\n            return SkillSpec(\n                id=skill_meta[\"id\"],\n                name=skill_meta[\"name\"],\n                author=skill_meta[\"author\"],\n                language=skill_meta[\"language\"],\n                category=skill_meta[\"category\"],\n                source=skill_meta[\"source\"] + (f\"#{skill_meta['subdir']}\" if skill_meta.get(\"subdir\") else \"\"),\n                system_prompt=loaded.to_system_prompt(),\n            )\n\n    # BYO: GitHub URL or local path\n    if skill_id_or_path.startswith((\"http://\", \"https://\", \"git@\", \"/\", \"./\", \"~/\")):\n        byo_source, byo_subdir = split_byo_source(skill_id_or_path)\n        loaded = load_skill(skill_id=\"byo\", source=byo_source, subdir=byo_subdir)\n        return SkillSpec(\n            id=\"byo:\" + loaded.name,\n            name=loaded.name + \" (BYO)\",\n            author=\"(user-provided)\",\n            language=\"—\",\n            category=\"byo\",\n            source=skill_id_or_path,\n            system_prompt=loaded.to_system_prompt(),\n        )\n\n    raise KeyError(\n        f\"Skill {skill_id_or_path!r} not found in catalog and not a recognizable URL/path. \"\n        f\"Available catalog IDs: {[s['id'] for s in catalog.get('skills', [])]}\"\n    )\n\n\n# --- Execution ---\n\ndef estimate_text_tokens(text: str) -> int:\n    \"\"\"\n    Rough token estimate for visible prompt/input/output text.\n\n    We avoid depending on provider-specific tokenizers here because forkprobe can\n    run across Claude Code, Codex native CLI, and API fallback paths. The estimate\n    intentionally favors stable cross-candidate comparison over provider billing\n    precision.\n    \"\"\"\n    if not text:\n        return 0\n\n    cjk = 0\n    latin_like = 0\n    other = 0\n    for ch in text:\n        code = ord(ch)\n        if ch.isspace():\n            continue\n        if (\n            0x3400 <= code <= 0x4DBF\n            or 0x4E00 <= code <= 0x9FFF\n            or 0xF900 <= code <= 0xFAFF\n        ):\n            cjk += 1\n        elif code < 128:\n            latin_like += 1\n        else:\n            other += 1\n\n    return max(1, round(cjk * 0.75 + latin_like / 4 + other / 3))\n\n\ndef estimate_run_tokens(task_input: str, system_prompt: str, output: str) -> int:\n    \"\"\"Estimate visible token load for one candidate run.\"\"\"\n    return estimate_text_tokens(system_prompt) + estimate_text_tokens(task_input) + estimate_text_tokens(output)\n\n\ndef skill_prompt_fingerprint(system_prompt: str) -> str:\n    \"\"\"Hash skill instructions while ignoring checkout-specific package paths.\"\"\"\n    normalized = re.sub(\n        r\"^Skill package path:.*$\",\n        \"Skill package path: <normalized>\",\n        system_prompt,\n        flags=re.MULTILINE,\n    )\n    normalized = \"\\n\".join(line.rstrip() for line in normalized.strip().splitlines())\n    return hashlib.sha256(normalized.encode(\"utf-8\")).hexdigest()\n\n\ndef dedupe_skill_specs(skills: list[SkillSpec]) -> list[SkillSpec]:\n    \"\"\"Remove semantically identical Skill packages before candidate execution.\"\"\"\n    deduped: list[SkillSpec] = []\n    seen: set[str] = set()\n    for skill in skills:\n        key = \"baseline\" if skill.id == \"baseline\" else skill_prompt_fingerprint(skill.system_prompt)\n        if key in seen:\n            continue\n        seen.add(key)\n        deduped.append(skill)\n    return deduped\n\n\ndef count_cjk_characters(text: str) -> int:\n    \"\"\"Count Han characters for deterministic Chinese-length checks.\"\"\"\n    return sum(\n        1\n        for char in text\n        if 0x3400 <= ord(char) <= 0x4DBF\n        or 0x4E00 <= ord(char) <= 0x9FFF\n        or 0xF900 <= ord(char) <= 0xFAFF\n    )\n\n\ndef _requested_cjk_range(task_input: str) -> Optional[tuple[int, int, str]]:\n    \"\"\"Extract an explicit Chinese character-count requirement from the task.\"\"\"\n    unit = r\"(?:个)?(?:汉字|中文字|中文字符|字)\"\n    range_match = re.search(rf\"(\\d{{2,4}})\\s*(?:[-~～—–至到])\\s*(\\d{{2,4}})\\s*{unit}\", task_input)\n    if range_match:\n        lower, upper = sorted((int(range_match.group(1)), int(range_match.group(2))))\n        return lower, upper, f\"{lower}-{upper} Chinese characters\"\n\n    max_match = re.search(rf\"(?:不超过|最多|至多|上限(?:为|是)?)\\s*(\\d{{2,4}})\\s*{unit}\", task_input)\n    if max_match:\n        upper = int(max_match.group(1))\n        return 0, upper, f\"at most {upper} Chinese characters\"\n\n    min_match = re.search(rf\"(?:不少于|至少|下限(?:为|是)?)\\s*(\\d{{2,4}})\\s*{unit}\", task_input)\n    if min_match:\n        lower = int(min_match.group(1))\n        return lower, 10**9, f\"at least {lower} Chinese characters\"\n\n    target_match = re.search(rf\"(?:约|大约|控制在|保持在)?\\s*(\\d{{2,4}})\\s*{unit}(?:左右)?\", task_input)\n    if target_match:\n        target = int(target_match.group(1))\n        tolerance = max(5, round(target * 0.1))\n        return max(0, target - tolerance), target + tolerance, f\"about {target} Chinese characters\"\n    return None\n\n\ndef text_constraint_warnings(task_input: str, output: str) -> list[str]:\n    \"\"\"Return deterministic QA warnings for explicit Chinese length constraints.\"\"\"\n    requested = _requested_cjk_range(task_input)\n    if not requested or not output:\n        return []\n    lower, upper, description = requested\n    actual = count_cjk_characters(output)\n    if lower <= actual <= upper:\n        return []\n    return [\n        f\"Length requirement not met: requested {description}; output contains {actual} Chinese characters.\"\n    ]\n\n\ndef run_one(task_input: str, skill: SkillSpec, platform, timeout: int = 120) -> RunResult:\n    \"\"\"Run a single subagent for one skill.\"\"\"\n    result: SubagentResult = spawn_subagent(\n        platform=platform,\n        task_input=task_input,\n        system_prompt=skill.system_prompt,\n        skill_id=skill.id,\n        timeout_seconds=timeout,\n    )\n    estimated_tokens = estimate_run_tokens(task_input, skill.system_prompt, result.output)\n    token_count_method = getattr(result, \"token_count_method\", \"provider_reported\")\n    provider_tokens = result.tokens_used if token_count_method == \"provider_reported\" else 0\n    return RunResult(\n        skill_id=skill.id,\n        skill_name=skill.name,\n        skill_author=skill.author,\n        skill_category=skill.category,\n        output=result.output,\n        tokens_used=result.tokens_used,\n        latency_seconds=result.latency_seconds,\n        estimated_tokens_used=estimated_tokens,\n        provider_tokens_used=provider_tokens,\n        token_count_method=token_count_method,\n        qa_warnings=text_constraint_warnings(task_input, result.output),\n        error=result.error,\n    )\n\n\ndef run_parallel(task_input: str, skills: list[SkillSpec], max_workers: int = 3) -> list[RunResult]:\n    \"\"\"\n    Run all skills in parallel and collect results.\n\n    Default max_workers=3 — empirically more reliable than 4-5 for skills with large\n    SKILL.md prompts (avoids transient rate-limit / quota errors on bursts).\n    Override with FORKPROBE_MAX_WORKERS env var if needed.\n    \"\"\"\n    import os\n    max_workers = int(os.environ.get(\"FORKPROBE_MAX_WORKERS\", str(max_workers)))\n    platform = detect_platform()\n    print(f\"[forkprobe] Platform: {platform.value}\")\n    print(f\"[forkprobe] Running {len(skills)} paths (concurrency={min(max_workers, len(skills))})...\")\n\n    results: list[RunResult] = []\n    with ThreadPoolExecutor(max_workers=max_workers) as ex:\n        futures = {ex.submit(run_one, task_input, skill, platform): skill for skill in skills}\n        for fut in as_completed(futures):\n            skill = futures[fut]\n            try:\n                result = fut.result()\n                status = \"✓\" if not result.error else \"✗\"\n                print(f\"[forkprobe]   {status} {skill.id} ({result.latency_seconds:.1f}s)\")\n                results.append(result)\n            except Exception as e:\n                print(f\"[forkprobe]   ✗ {skill.id} crashed: {e}\")\n                results.append(RunResult(\n                    skill_id=skill.id, skill_name=skill.name, skill_author=skill.author,\n                    skill_category=skill.category, output=\"\", tokens_used=0, latency_seconds=0.0,\n                    estimated_tokens_used=estimate_run_tokens(task_input, skill.system_prompt, \"\"),\n                    provider_tokens_used=0,\n                    token_count_method=\"unavailable\",\n                    error=str(e),\n                ))\n\n    # Preserve input order (baseline first if present)\n    order = {s.id: i for i, s in enumerate(skills)}\n    results.sort(key=lambda r: order.get(r.skill_id, 999))\n    return results\n\n\n# --- Judge ---\n\nJUDGE_SYSTEM_PROMPT = \"\"\"You are forkprobe's impartial comparison judge.\n\nYour job is to compare candidate outputs for the same user task. Do not rewrite\nthe answer. Do not choose based on style alone. Judge which candidate best serves\nthe user's original task.\n\nEvaluate candidates on:\n- fidelity to the user's original intent\n- correctness and specificity\n- usefulness for the requested domain\n- clarity and readability\n- for academic writing tasks: natural scholarly tone, reduced AI-like boilerplate,\n  and preservation of meaning\n\nUse a 0-10 scale for every candidate score, where 10 is best.\n\nReturn JSON only, with this exact shape:\n{\n  \"winner_skill_id\": \"one candidate id, __tie__, or __none__\",\n  \"verdict_type\": \"pick | tie | none\",\n  \"confidence\": 0.0,\n  \"summary\": \"one concise sentence\",\n  \"reasoning\": \"2-5 concise sentences\",\n  \"scores\": {\n    \"candidate_id\": {\"score\": 0, \"note\": \"short note\"}\n  }\n}\n\nUse the same language as the user's task when possible.\n\"\"\"\n\n\ndef _truncate(text: str, limit: int = 6000) -> str:\n    \"\"\"Keep judge prompts bounded while preserving the start and end of long outputs.\"\"\"\n    if len(text) <= limit:\n        return text\n    head = text[: limit // 2]\n    tail = text[-limit // 2 :]\n    return f\"{head}\\n\\n[... truncated {len(text) - limit} chars ...]\\n\\n{tail}\"\n\n\ndef build_judge_task(task_input: str, results: list[RunResult], rubric: Optional[str] = None) -> str:\n    \"\"\"Build the user message sent to the judge subagent.\"\"\"\n    candidate_blocks = []\n    for r in results:\n        if r.error:\n            body = f\"[ERROR] {r.error}\"\n        else:\n            body = _truncate(r.output, limit=5000)\n        candidate_blocks.append(\n            f\"## Candidate: {r.skill_id}\\n\"\n            f\"Name: {r.skill_name}\\n\"\n            f\"Category: {r.skill_category}\\n\"\n            f\"Tokens: {r.tokens_used}\\n\"\n            f\"Latency: {r.latency_seconds:.1f}s\\n\"\n            f\"Deterministic QA: {'; '.join(r.qa_warnings) if r.qa_warnings else 'passed'}\\n\\n\"\n            f\"{body}\"\n        )\n\n    rubric_section = f\"\\n\\n## User rubric\\n{rubric}\" if rubric else \"\"\n    return (\n        \"Compare the following forkprobe candidates and recommend a winner.\\n\\n\"\n        f\"## Original task\\n{_truncate(task_input, limit=4000)}\"\n        f\"{rubric_section}\\n\\n\"\n        \"## Candidates\\n\\n\"\n        + \"\\n\\n---\\n\\n\".join(candidate_blocks)\n    )\n\n\ndef _extract_json_object(text: str) -> Optional[dict]:\n    \"\"\"Parse a JSON object from model output, tolerating fenced code or preamble.\"\"\"\n    text = text.strip()\n    if not text:\n        return None\n    try:\n        return json.loads(text)\n    except json.JSONDecodeError:\n        try:\n            return json.loads(text, strict=False)\n        except json.JSONDecodeError:\n            pass\n\n    start = text.find(\"{\")\n    end = text.rfind(\"}\")\n    if start == -1 or end == -1 or end <= start:\n        return None\n    try:\n        return json.loads(text[start : end + 1])\n    except json.JSONDecodeError:\n        try:\n            return json.loads(text[start : end + 1], strict=False)\n        except json.JSONDecodeError:\n            return None\n\n\ndef parse_judge_output(output: str, results: list[RunResult], tokens: int, latency: float) -> JudgeResult:\n    \"\"\"Convert the judge model's JSON into a stable JudgeResult.\"\"\"\n    parsed = _extract_json_object(output)\n    valid_ids = {r.skill_id for r in results}\n    valid_ids.update({\"__tie__\", \"__none__\"})\n    if not parsed:\n        return JudgeResult(\n            winner_skill_id=None,\n            verdict_type=\"none\",\n            confidence=None,\n            summary=\"Judge returned non-JSON output.\",\n            reasoning=\"The raw judge output is included for debugging.\",\n            scores={},\n            tokens_used=tokens,\n            latency_seconds=latency,\n            error=\"Could not parse judge JSON.\",\n            raw_output=output,\n        )\n\n    winner = parsed.get(\"winner_skill_id\")\n    if winner not in valid_ids:\n        winner = None\n    verdict_type = parsed.get(\"verdict_type\") or (\"tie\" if winner == \"__tie__\" else \"none\" if winner == \"__none__\" else \"pick\")\n    if verdict_type not in {\"pick\", \"tie\", \"none\"}:\n        verdict_type = \"pick\" if winner else \"none\"\n    if verdict_type == \"tie\":\n        winner = \"__tie__\"\n    elif verdict_type == \"none\":\n        winner = \"__none__\"\n\n    confidence = parsed.get(\"confidence\")\n    try:\n        confidence = float(confidence) if confidence is not None else None\n    except (TypeError, ValueError):\n        confidence = None\n    if confidence is not None:\n        confidence = max(0.0, min(1.0, confidence))\n\n    valid_winner = winner in valid_ids\n\n    return JudgeResult(\n        winner_skill_id=winner,\n        verdict_type=verdict_type,\n        confidence=confidence,\n        summary=str(parsed.get(\"summary\") or \"\"),\n        reasoning=str(parsed.get(\"reasoning\") or \"\"),\n        scores=parsed.get(\"scores\") if isinstance(parsed.get(\"scores\"), dict) else {},\n        tokens_used=tokens,\n        latency_seconds=latency,\n        error=None if valid_winner else \"Judge did not choose a valid winner.\",\n        raw_output=output,\n    )\n\n\ndef run_judge(task_input: str, results: list[RunResult], rubric: Optional[str] = None, timeout: int = 120) -> JudgeResult:\n    \"\"\"Run a judge subagent after candidate generation.\"\"\"\n    platform = detect_platform()\n    print(f\"[forkprobe] Judge: running on {platform.value}...\")\n    judge_task = build_judge_task(task_input, results, rubric=rubric)\n    result = spawn_subagent(\n        platform=platform,\n        task_input=judge_task,\n        system_prompt=JUDGE_SYSTEM_PROMPT,\n        skill_id=\"__judge__\",\n        timeout_seconds=timeout,\n    )\n    if result.error:\n        print(f\"[forkprobe]   ✗ judge failed: {result.error}\")\n        return JudgeResult(\n            winner_skill_id=None,\n            verdict_type=\"none\",\n            confidence=None,\n            summary=\"Judge failed.\",\n            reasoning=result.error,\n            scores={},\n            tokens_used=result.tokens_used,\n            latency_seconds=result.latency_seconds,\n            error=result.error,\n            raw_output=result.output,\n        )\n    judge = parse_judge_output(result.output, results, result.tokens_used, result.latency_seconds)\n    status = \"✓\" if not judge.error else \"✗\"\n    print(f\"[forkprobe]   {status} judge recommendation: {judge.winner_skill_id or '(none)'} ({judge.latency_seconds:.1f}s)\")\n    return judge\n\n\n# --- Logging ---\n\ndef write_log(\n    task_input: str,\n    results: list[RunResult],\n    output_path: Path,\n    judge_result: Optional[JudgeResult] = None,\n    task_type: str = \"text_general\",\n    platform_name: Optional[str] = None,\n    logs_dir: Optional[Path] = None,\n) -> Path:\n    \"\"\"Append a log entry to forkprobe-logs/. Stores HASH only, never content.\"\"\"\n    active_logs_dir = logs_dir or LOGS_DIR\n    active_logs_dir.mkdir(parents=True, exist_ok=True)\n    timestamp = time.strftime(\"%Y-%m-%dT%H:%M:%SZ\", time.gmtime())\n    run_id = str(uuid.uuid4())[:8]\n    log_file = active_logs_dir / f\"{timestamp.replace(':', '')}-{run_id}.json\"\n\n    log_entry = {\n        \"timestamp\": timestamp,\n        \"run_id\": run_id,\n        \"platform\": platform_name or detect_platform().value,\n        \"task_type\": task_type,\n        \"task_input_hash\": \"sha256:\" + hashlib.sha256(task_input.encode(\"utf-8\")).hexdigest(),\n        \"task_input_chars\": len(task_input),\n        \"candidates\": [\n            {\n                \"id\": r.skill_id,\n                \"name\": r.skill_name,\n                \"tokens_used\": r.tokens_used,\n                \"provider_tokens_used\": r.provider_tokens_used,\n                \"estimated_tokens_used\": r.estimated_tokens_used,\n                \"token_count_method\": r.token_count_method,\n                \"latency_seconds\": r.latency_seconds,\n                \"had_error\": bool(r.error),\n            }\n            for r in results\n        ],\n        \"judge\": asdict(judge_result) if judge_result else None,\n        \"verdict\": None,  # filled in later by HTML report interaction\n        \"report_path\": str(output_path.resolve()),\n    }\n    log_file.write_text(json.dumps(log_entry, indent=2), encoding=\"utf-8\")\n    return log_file\n\n\n# --- CLI ---\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=\"forkprobe: compare a task with and without skills\",\n    )\n    parser.add_argument(\"--input\", required=True, help=\"Path to task input file\")\n    parser.add_argument(\"--skill\", action=\"append\", default=[],\n                        help=\"Skill ID (from catalog) or path/URL (BYO). Repeat for multiple. Use 'baseline' for bare model.\")\n    parser.add_argument(\"--output\", default=\"./report.html\", help=\"Output HTML report path\")\n    parser.add_argument(\"--domain\", default=\"academic-writing\", help=\"Catalog domain (default: academic-writing)\")\n    parser.add_argument(\"--task-type\", default=\"text_general\",\n                        help=\"Privacy-safe task category used for anonymous aggregate selection stats\")\n    parser.add_argument(\n        \"--platform\",\n        choices=[\"auto\", \"claude_code\", \"codex\", \"deepseek_harness\", \"standalone\"],\n        default=\"auto\",\n        help=\"Agent harness for candidate execution (default: auto-detect)\",\n    )\n    parser.add_argument(\"--no-server\", action=\"store_true\",\n                        help=\"Skip the verdict-capture server (report still renders, but verdict goes to browser console only)\")\n    parser.add_argument(\"--verdict-timeout\", type=int, default=600,\n                        help=\"Seconds to wait for the user to submit a verdict (default: 600 = 10 min)\")\n    parser.add_argument(\"--judge\", action=\"store_true\",\n                        help=\"Run an extra AI judge after candidate generation and show its recommendation in the report\")\n    parser.add_argument(\"--judge-rubric\", default=None,\n                        help=\"Optional extra rubric text for --judge (e.g. 'prefer concise Chinese academic prose')\")\n    parser.add_argument(\"--judge-timeout\", type=int, default=120,\n                        help=\"Seconds to wait for the judge subagent (default: 120)\")\n    args = parser.parse_args()\n\n    if args.platform != \"auto\":\n        os.environ[\"FORKPROBE_PLATFORM\"] = args.platform\n\n    # Load input\n    input_path = Path(args.input)\n    if not input_path.exists():\n        print(f\"Error: input file not found: {input_path}\", file=sys.stderr)\n        sys.exit(1)\n    task_input = input_path.read_text(encoding=\"utf-8\")\n\n    # Ensure baseline is always present\n    skill_ids = list(args.skill)\n    if \"baseline\" not in skill_ids:\n        skill_ids.insert(0, \"baseline\")\n\n    # Load catalog and resolve skills\n    catalog = load_catalog(args.domain)\n    try:\n        skills = dedupe_skill_specs([resolve_skill(sid, catalog) for sid in skill_ids])\n    except (NotImplementedError, KeyError) as e:\n        print(f\"Error resolving skill: {e}\", file=sys.stderr)\n        sys.exit(1)\n\n    print(f\"[forkprobe] {FORKPROBE_VERSION}\")\n    print(f\"[forkprobe] Task input: {len(task_input)} chars from {input_path}\")\n    print(f\"[forkprobe] Skills to compare: {[s.id for s in skills]}\")\n    print()\n\n    # Run\n    t0 = time.time()\n    results = run_parallel(task_input, skills)\n    candidate_duration = time.time() - t0\n    print(f\"\\n[forkprobe] Done in {candidate_duration:.1f}s\")\n\n    judge_result = None\n    if args.judge:\n        judge_result = run_judge(\n            task_input=task_input,\n            results=results,\n            rubric=args.judge_rubric,\n            timeout=args.judge_timeout,\n        )\n    duration = time.time() - t0\n\n    # Log first so the verdict server can write back to it\n    output_path = Path(args.output)\n    log_file = write_log(\n        task_input,\n        results,\n        output_path,\n        judge_result=judge_result,\n        task_type=args.task_type,\n    )\n    print(f\"[forkprobe] Log: {log_file}\")\n\n    # Start verdict-capture server (D4)\n    verdict_url = None\n    stop_verdict_server = None\n    if not args.no_server:\n        try:\n            from verdict_server import build_verdict_url, start_server, wait_for_verdict, stop_server\n            port = start_server(log_file)\n            verdict_url = build_verdict_url(port)\n            stop_verdict_server = stop_server\n            print(f\"[forkprobe] Verdict server: loopback-only endpoint ready on port {port}\")\n        except Exception as e:\n            print(f\"[forkprobe] Could not start verdict server ({e}). Continuing without it.\")\n\n    # Render report\n    try:\n        from render_report import render\n        render(\n            task_input=task_input,\n            results=[asdict(r) for r in results],\n            duration_seconds=duration,\n            output_path=output_path,\n            verdict_url=verdict_url,\n            judge_result=asdict(judge_result) if judge_result else None,\n        )\n        print(f\"[forkprobe] Report: {output_path.resolve()}\")\n    except (ImportError, RuntimeError) as e:\n        print(f\"[forkprobe] Report rendering failed: {e}\", file=sys.stderr)\n        if stop_verdict_server:\n            stop_verdict_server()\n        sys.exit(1)\n\n    # Wait for the user's verdict (or timeout)\n    if verdict_url:\n        try:\n            print(f\"[forkprobe] Waiting up to {args.verdict_timeout}s for your verdict in the browser...\")\n            verdict = wait_for_verdict(timeout_seconds=args.verdict_timeout)\n            if verdict:\n                print(f\"[forkprobe] ✓ Verdict captured: winner={verdict.get('winner')}, type={verdict.get('verdict_type')}\")\n                handoff_text = verdict.get(\"handoff_text\")\n                if handoff_text:\n                    print(\"\\n[forkprobe] Continuation handoff (copy back into your agent session if it does not continue automatically):\")\n                    print(handoff_text)\n                if verdict.get(\"handoff_path\"):\n                    print(f\"[forkprobe] Handoff file: {verdict.get('handoff_path')}\")\n            else:\n                print(f\"[forkprobe] No verdict received before timeout. Log retained anyway.\")\n        finally:\n            if stop_verdict_server:\n                stop_verdict_server()\n\n\nif __name__ == \"__main__\":\n    main()\n"
    },
    {
      "path": "scripts/finalize_native_compare.py",
      "content": "\"\"\"Finalize native DSH subagent results into ForkProbe's Report workflow.\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport subprocess\nimport sys\nimport time\nfrom dataclasses import asdict\nfrom pathlib import Path\n\nfrom compare import (\n    JudgeResult,\n    RunResult,\n    estimate_run_tokens,\n    parse_judge_output,\n    text_constraint_warnings,\n    write_log,\n)\nfrom render_report import open_report, render\nfrom verdict_server import build_verdict_url\n\n\ndef _start_verdict_process(log_file: Path, timeout_seconds: int) -> tuple[str | None, int | None]:\n    run_id = log_file.stem\n    port_file = log_file.parent / f\".{run_id}.port\"\n    server_log = log_file.parent / f\"{run_id}.verdict-server.log\"\n    port_file.unlink(missing_ok=True)\n    with server_log.open(\"ab\") as stream:\n        process = subprocess.Popen(\n            [\n                sys.executable,\n                str(Path(__file__).with_name(\"run_verdict_server_once.py\")),\n                \"--log\",\n                str(log_file),\n                \"--port-file\",\n                str(port_file),\n                \"--timeout\",\n                str(timeout_seconds),\n            ],\n            stdin=subprocess.DEVNULL,\n            stdout=stream,\n            stderr=subprocess.STDOUT,\n            start_new_session=True,\n            close_fds=True,\n        )\n\n    deadline = time.monotonic() + 8\n    while time.monotonic() < deadline:\n        if process.poll() is not None:\n            return None, None\n        if port_file.exists():\n            try:\n                endpoint = port_file.read_text(encoding=\"utf-8\").strip()\n                if endpoint.startswith(\"http://localhost:\"):\n                    return endpoint, process.pid\n                # Backward compatibility with an older helper that wrote only a port.\n                return build_verdict_url(int(endpoint)), process.pid\n            except (OSError, ValueError):\n                pass\n        time.sleep(0.1)\n    process.terminate()\n    return None, None\n\n\ndef _run_result(task_input: str, value: dict) -> RunResult:\n    output = str(value.get(\"output\") or \"\")\n    system_prompt = str(value.get(\"system_prompt\") or \"\")\n    token_method = str(value.get(\"token_count_method\") or \"estimated_visible_context\")\n    provider_tokens = int(value.get(\"provider_tokens_used\") or 0) if token_method == \"provider_reported\" else 0\n    estimated_tokens = int(value.get(\"estimated_tokens_used\") or 0) or estimate_run_tokens(\n        task_input,\n        system_prompt,\n        output,\n    )\n    return RunResult(\n        skill_id=str(value.get(\"skill_id\") or \"unknown\"),\n        skill_name=str(value.get(\"skill_name\") or value.get(\"skill_id\") or \"Unknown\"),\n        skill_author=str(value.get(\"skill_author\") or \"\"),\n        skill_category=str(value.get(\"skill_category\") or \"\"),\n        output=output,\n        tokens_used=provider_tokens,\n        latency_seconds=float(value.get(\"latency_seconds\") or 0),\n        estimated_tokens_used=estimated_tokens,\n        provider_tokens_used=provider_tokens,\n        token_count_method=token_method,\n        qa_warnings=text_constraint_warnings(task_input, output),\n        error=str(value.get(\"error\")) if value.get(\"error\") else None,\n    )\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=\"Render a ForkProbe report from native DSH subagent results\")\n    parser.add_argument(\"--manifest\", required=True)\n    parser.add_argument(\"--output\", required=True)\n    parser.add_argument(\"--workspace\", required=True)\n    parser.add_argument(\"--verdict-timeout\", type=int, default=1800)\n    parser.add_argument(\"--no-server\", action=\"store_true\")\n    parser.add_argument(\"--no-open\", action=\"store_true\")\n    args = parser.parse_args()\n\n    manifest_path = Path(args.manifest).resolve()\n    manifest = json.loads(manifest_path.read_text(encoding=\"utf-8\"))\n    if manifest.get(\"schema_version\") != 1:\n        raise ValueError(\"unsupported native DSH manifest schema\")\n\n    task_input = str(manifest.get(\"task_input\") or \"\")\n    results = [_run_result(task_input, value) for value in manifest.get(\"results\") or []]\n    if len(results) < 2:\n        raise ValueError(\"native DSH manifest must contain at least two candidates\")\n\n    judge_result: JudgeResult | None = None\n    judge = manifest.get(\"judge\")\n    if isinstance(judge, dict) and judge.get(\"enabled\"):\n        if judge.get(\"error\"):\n            judge_result = JudgeResult(\n                winner_skill_id=None,\n                verdict_type=\"none\",\n                confidence=None,\n                summary=\"Judge failed.\",\n                reasoning=str(judge.get(\"error\")),\n                scores={},\n                tokens_used=0,\n                latency_seconds=float(judge.get(\"latency_seconds\") or 0),\n                error=str(judge.get(\"error\")),\n                raw_output=str(judge.get(\"output\") or \"\"),\n            )\n        else:\n            judge_result = parse_judge_output(\n                str(judge.get(\"output\") or \"\"),\n                results,\n                0,\n                float(judge.get(\"latency_seconds\") or 0),\n            )\n\n    output_path = Path(args.output).resolve()\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    workspace = Path(args.workspace).resolve()\n    logs_dir = workspace / \"forkprobe-logs\"\n    log_file = write_log(\n        task_input,\n        results,\n        output_path,\n        judge_result=judge_result,\n        task_type=str(manifest.get(\"task_type\") or \"text_general\"),\n        platform_name=\"deepseek_harness_native\",\n        logs_dir=logs_dir,\n    )\n\n    local_bundle = output_path.with_suffix(\".forkprobe-run.json\")\n    local_bundle.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n    log = json.loads(log_file.read_text(encoding=\"utf-8\"))\n    log[\"execution_mode\"] = \"native_dsh_plugin\"\n    log[\"local_result_bundle_path\"] = str(local_bundle)\n    log_file.write_text(json.dumps(log, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n\n    verdict_url = None\n    server_pid = None\n    if not args.no_server:\n        verdict_url, server_pid = _start_verdict_process(log_file, args.verdict_timeout)\n\n    render(\n        task_input=task_input,\n        results=[asdict(result) for result in results],\n        duration_seconds=float(manifest.get(\"duration_seconds\") or 0),\n        output_path=output_path,\n        auto_open=False,\n        verdict_url=verdict_url,\n        judge_result=asdict(judge_result) if judge_result else None,\n    )\n    opened = False if args.no_open else open_report(output_path)\n\n    response = {\n        \"status\": \"ready\",\n        \"report_path\": str(output_path),\n        \"log_path\": str(log_file),\n        \"local_result_bundle_path\": str(local_bundle),\n        \"verdict_connected\": bool(verdict_url),\n        \"verdict_server_pid\": server_pid,\n        \"report_opened\": opened,\n        \"judge_winner\": judge_result.winner_skill_id if judge_result else None,\n        \"candidate_count\": len(results),\n    }\n    print(json.dumps(response, ensure_ascii=False))\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"
